<script setup>
import {ref,onMounted,onBeforeUnmount,nextTick} from 'vue'
import {useScroll,useWindowSize,usePreferredReducedMotion} from '@vueuse/core'
import gsap from 'gsap';import {ScrollTrigger} from 'gsap/ScrollTrigger';import Lenis from 'lenis'
import {chapters} from './data/chapters';import HeroSection from './components/HeroSection.vue';import ReadingProgress from './components/ReadingProgress.vue';import TableOfContents from './components/TableOfContents.vue';import ChapterBlock from './components/ChapterBlock.vue';import ConclusionsBlock from './components/ConclusionsBlock.vue';import SourcesList from './components/SourcesList.vue';import SiteFooter from './components/SiteFooter.vue'
gsap.registerPlugin(ScrollTrigger)
const active=ref('why'),progress=ref(0),{width}=useWindowSize(),reduced=usePreferredReducedMotion();useScroll(window);let lenis,observer,ctx,ticker;const navigate=id=>{const el=document.getElementById(id);if(!el)return;history.replaceState(null,'','#'+id);if(lenis)lenis.scrollTo(el,{offset:-35,duration:1.1});else el.scrollIntoView({behavior:reduced.value==='reduce'?'instant':'smooth'});active.value=id}
function updateProgress(){const max=document.documentElement.scrollHeight-window.innerHeight;progress.value=max?Math.min(1,window.scrollY/max):0}
onMounted(async()=>{await nextTick();if(reduced.value!=='reduce'&&width.value>768){lenis=new Lenis({smoothWheel:true,duration:1.05});lenis.on('scroll',ScrollTrigger.update);ticker=time=>lenis.raf(time*1000);gsap.ticker.add(ticker);gsap.ticker.lagSmoothing(0)}observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting)active.value=e.target.id})},{rootMargin:'-10% 0px -65% 0px',threshold:0});document.querySelectorAll('.chapter,#conclusions').forEach(el=>observer.observe(el));window.addEventListener('scroll',updateProgress,{passive:true});updateProgress();if(reduced.value!=='reduce'){ctx=gsap.context(()=>{gsap.utils.toArray('.chapter-header,.conclusion').forEach(el=>gsap.from(el,{y:35,opacity:0,duration:.8,ease:'power2.out',scrollTrigger:{trigger:el,start:'top 94%',once:true}}));gsap.from('.case-card',{opacity:0,y:20,stagger:.12,duration:.7,ease:'power2.out',scrollTrigger:{trigger:'.cases-grid',start:'top 90%',once:true}});const mm=gsap.matchMedia();mm.add('(min-width: 1100px)',()=>{const rows=gsap.utils.toArray('.thesis-line');gsap.timeline({scrollTrigger:{trigger:'.thesis',start:'top 18%',end:'+=950',pin:true,scrub:1}}).fromTo(rows[1],{opacity:.18},{opacity:1,duration:1}).fromTo(rows[2],{opacity:.18},{opacity:1,duration:1})})})}document.fonts.ready.then(()=>ScrollTrigger.refresh())})
onBeforeUnmount(()=>{observer?.disconnect();window.removeEventListener('scroll',updateProgress);lenis?.destroy();if(ticker)gsap.ticker.remove(ticker);ctx?.revert()})
</script><template><a class="skip-link" href="#why">Перейти к тексту</a><ReadingProgress :progress="progress"/><HeroSection @start="navigate"/><div class="reading-layout"><aside class="toc-column"><TableOfContents :chapters="chapters" :active="active" :progress="progress" @navigate="navigate"/></aside><main id="main"><ChapterBlock v-for="chapter in chapters" :key="chapter.id" :chapter="chapter"/><section class="thesis" aria-label="Приоритет технологий"><p class="eyebrow">ОТ ИНФРАСТРУКТУРЫ К ДОВЕРИЮ</p><p class="thesis-line">Облака <span>дают основу.</span></p><p class="thesis-line">ИИ <span>усиливает решения.</span></p><p class="thesis-line">Реестры <span>фиксируют права.</span></p></section><ConclusionsBlock/></main></div><SourcesList/><SiteFooter/></template>
